ImageWithTextProps.declaration:
export interface ImageWithTextProps {
  readonly image?: string;
  /**
   * The heading markup. MUST be pre-sanitized by the caller before reaching this prop — it renders via
   * `dangerouslySetInnerHTML` so a merchant-authored `<strong>`/`<em>` split (the legacy heading grammar)
   * survives instead of being flattened to plain text. This mirrors the codebase's established
   * sanitize-at-the-seam pattern (`sanitize-merchant-html.ts`'s `sanitizeMerchantHtml`, and the vendored
   * `l2-legacy-sections` modules' own `dangerouslySetInnerHTML={{ __html: … }}` usages) — this component
   * trusts its caller the same way those do; it performs no sanitization of its own.
   */
  readonly heading?: string;
  /**
   * The body markup. Like {@link ImageWithTextProps.heading}, MUST be pre-sanitized by the caller — it
   * renders via `dangerouslySetInnerHTML` (legacy parity: the body is a rich-text field, so bold/italic
   * survives). The caller (`NexusImageWithTextAdapter`) routes it through the same C-1 `sanitizeMerchantHtml`
   * allowlist as `heading`.
   */
  readonly text?: string;
  readonly ctaLabel?: string;
  /**
   * A destination the CTA navigates to. When supplied (and non-empty), the CTA renders as a real
   * `<a href>` (legacy parity: the CTA is a `<Link>`). When absent, the CTA falls back to the token
   * `<Button>` driven by {@link ImageWithTextProps.onCta}. MUST be pre-sanitized by the caller (the
   * adapter routes it through `sanitizeHref`).
   */
  readonly ctaHref?: string;
  readonly onCta?: () => void;
  /** Which column the image sits in (for the `split` layout). Defaults to `start`. */
  readonly imageSide?: ImageSide;
  /** The image/text presentation. Defaults to `split`. */
  readonly layout?: ImageWithTextLayout;
  /** Image focal point (`object-position`); defaults to centered (50/50). */
  readonly focalPoint?: ImageFocalPoint;
  /** How the text-column content aligns. Defaults to `start`. */
  readonly contentAlignment?: ImageWithTextAlignment;
  /** Gap between the image and text columns, in px. Defaults to the token `calc(var(--space) * 2)`. */
  readonly columnGapPx?: number;
  /** The section's inner max content width, in px. Unset = full width (token behavior). */
  readonly maxWidthPx?: number;
  /** Per-section background color override (resolved CSS color). Unset = the token/transparent default. */
  readonly backgroundColor?: string;
  /** Per-section heading color override (resolved CSS color). */
  readonly headingColor?: string;
  /** Per-section body-text color override (resolved CSS color). */
  readonly textColor?: string;
  /** Per-section CTA background color override (resolved CSS color). */
  readonly ctaBackgroundColor?: string;
  /** Per-section CTA text color override (resolved CSS color). */
  readonly ctaTextColor?: string;
  /** Overlay tint color for the `overlay` layout (resolved CSS color). Defaults to black. */
  readonly overlayColor?: string;
  /** Overlay opacity percentage (0–100) for the `overlay` layout. Defaults to 50. */
  readonly overlayOpacity?: number;
  /** Heading size preset (legacy `title_size`). Defaults to `m` — legacy's own default, so a fresh,
   * unconfigured insert renders at legacy's real responsive scale (24px base / 30px ≥48rem-container,
   * see {@link TITLE_SIZE_REM}/{@link TITLE_SIZE_DESKTOP_REM}), never the browser's plain `<h2>` size. */
  readonly titleSize?: ImageWithTextTitleSize;
  /** Body size preset (legacy `text_size`). Defaults to `m` (16px base / 18px desktop), mirroring
   * {@link ImageWithTextProps.titleSize}. */
  readonly textSize?: ImageWithTextTextSize;
  /** Vertical-only section padding preset (legacy `section_spacing`). Defaults to `medium` (legacy's own
   * default). Horizontal padding stays the component's own fixed gutter — mirrors legacy's `py-*`-only
   * spacing class (horizontal padding is a separate, non-`sectionSpacing` concern in the oracle). */
  readonly sectionSpacing?: ImageWithTextSectionSpacing;
  /**
   * A fixed image-column pixel height. The real legacy oracle sizes this figure by a FIXED PIXEL
   * HEIGHT (keyed by the section's `image_height` preset), not a fixed aspect-ratio — `object-fit:
   * cover` on a fixed height naturally varies the effective ratio by container width, matching legacy.
   * Defaults to `380` (the legacy `medium` desktop token) when the caller doesn't resolve one. For the
   * `overlay` layout this is the section's minimum height.
   *
   * KNOWN GAP: legacy also varies this height at the `max-md` breakpoint (e.g. 380px → 280px on
   * mobile); a single inline pixel value cannot express that without a media query, so this component
   * renders ONE height across all viewports. Not required for this fix.
   */
  readonly imageHeightPx?: number;
}

